from lib import *
S = SS('f101')
R = J('f101'); ct = R['cost']
steps = [
    step("视图直接返回 dict 或 list,Flask 自动转成 JSON 响应(Content-Type: application/json),顶层列表也行;return {...}, 201, {'Location': '/items/7'} 同时设置状态码与响应头。默认值:app.json.sort_keys = True(键按字母排序,所以 b、a、c 输出成 a、b、c)、ensure_ascii = True(中文被转成 \\u4e2d\\u6587)、mimetype = application/json。", t=tl(S(1)), done=lidx(S(1), 'return {...}', 'jsonify', '顶层列表'), mark=lidx(S(1), '默认值'), kv=KV([['返回 dict / list', '自动 jsonify'], ['sort_keys', 'True,键会被排序'], ['ensure_ascii', 'True,中文转义']], ['sort_keys'])),
    step("能序列化的类型:datetime 与 date 变成 HTTP 日期格式的字符串(Fri, 02 Jan 2026 00:00:00 GMT,而不是 ISO 8601),Decimal 变成字符串(\"1.10\"),UUID 变成带连字符的字符串;set 默认不支持,视图抛 TypeError,响应是 500 的 HTML 错误页,而不是 JSON。", t=tl(S(2)), done=lidx(S(2), 'datetime'), mark=lidx(S(2), 'set'), kv=KV([['datetime', 'HTTP 日期字符串'], ['Decimal / UUID', '字符串'], ['set', '500,需要自定义']], ['datetime'])),
    step("request.get_json() 的各种情况:Content-Type 是 application/json 且 JSON 合法 → 200;JSON 非法 → 400 Bad Request;Content-Type 是 text/plain 或没有 → 415 Unsupported Media Type(合法 JSON 也不读);application/json 加空请求体 → 400。get_json(silent=True) 遇到非法 JSON 返回 None(这里是 {\"got\": null},200);get_json(force=True) 不看 Content-Type,text/plain 的合法 JSON 也能读到。注意这些错误响应默认都是 HTML 页面。", t=tl(S(3)), done=lidx(S(3), '合法 JSON', 'silent=True', 'force=True', 'json= 参数'), mark=lidx(S(3), '非法 JSON', 'text/plain', '没有 Content-Type', '空请求体'), kv=KV([['非法 JSON', '400'], ['Content-Type 不对', '415'], ['silent / force', '不报错 / 不看类型']], ['Content-Type 不对'])),
    step("视图返回 None 是 500(不是 204)——Flask 不接受 None 作为响应,错误页同样是 HTML;返回字符串则是 200 text/html。想要「没有内容」要明确返回 ('', 204)。", t=tl(S(4)), mark=lidx(S(4), 'return None'), done=lidx(S(4), 'plain'), kv=KV([['return None', '500'], ['return 字符串', '200 text/html']], ['return None'])),
    step("自定义序列化:继承 DefaultJSONProvider,设 ensure_ascii = False、sort_keys = False,并在 default 里把 set 转成排序的列表。同一份数据输出 {\"b\":1,\"a\":\"中文\",\"s\":[1,2]}(保留键的顺序、中文不转义、set 变成列表),默认 provider 对应的输出是 {\"a\":\"\\u4e2d\\u6587\",\"b\":1,\"c\":[1,2]}。", t=tl(S(5)), done=lidx(S(5), '"b":1', '默认 provider'), kv=KV([['app.json = MyProvider(app)', '全局替换序列化行为'], ['default()', '处理不认识的类型']], ['app.json = MyProvider(app)'])),
    step(f"序列化的开销:返回 1000 个对象的列表(响应 {ct[2]} 字节),经 Flask(test client)返回 {ct[0]:.2f} ms/次,纯 json.dumps {ct[1]:.2f} ms/次。JSON 序列化本身占了大头,Flask 自己的包装只多出一点;大响应的优化见第 117、118 篇。", b=bars([['经 Flask 返回', ct[0], f'{ct[0]:.2f} ms'], ['json.dumps', ct[1], f'{ct[1]:.2f} ms']], ct[0], done=[1], mark=[0]), t=tl(S(6)), done=lidx(S(6), '经 Flask'), kv=KV([['1000 个对象', f'{ct[0]:.2f} ms'], ['其中 json.dumps', f'{ct[1]:.2f} ms']], ['1000 个对象'])),
]
A = mkartf('f101', 101, 'Flask,JSON API,jsonify,get_json,真实验证,动画演示',
    '实测 Flask 实现 JSON API 的基本行为:返回 dict 与 list 自动转 JSON、默认排序键与转义中文、datetime 变成 HTTP 日期字符串而 set 不能序列化、get_json 在非法 JSON 与错误 Content-Type 时的 400 与 415、返回 None 是 500、自定义 JSON provider、序列化开销。',
    '用 Flask 写 JSON API,返回值与请求体各有哪些默认行为?哪些类型能序列化?请求头不对会返回什么?这篇用 test_client 把每种情况的状态码与响应逐个打印出来。',
    [('415', 'Content-Type 不是 application/json 时 get_json() 的状态码'), ('sort_keys', '默认为 True,返回的键会被排序'), ('500', '视图返回 None 或 set 时的状态码')],
    [('返回 dict、list 与 jsonify', '<p>上一篇:<a href="flask-db-reconnect.html">数据库连接断开后的恢复</a>;下一篇:<a href="flask-api-error-format.html">API 错误响应统一格式</a>。</p>'), ('可序列化的类型', None), ('读取请求体', None), ('None 与字符串', None), ('自定义 JSON provider', None), ('序列化的开销', None)],
    steps, [ENV_F, '没有验证:真实 HTTP 下 Content-Length 与分块编码对 get_json 的影响、超大请求体的限制(MAX_CONTENT_LENGTH)、其它 JSON 库(orjson)作为 provider 的效果、JSONP 与 JSON 安全问题', ], 'JSON API', panels=[('t', 'term', '实验输出'), ('b', 'bars', '耗时'), ('kv', 'kv', '要点')])
